recipes.code:
{
  "inputs": [
    {
      "id": "srg-api-keys",
      "type": "promptString",
      "description": "SRG+ workspace API key(s). Single key: srgplus_xxx. Multiple workspaces: srgplus_xxx,srgplus_yyy (comma-separated). Get keys from Settings -> Workspaces -> API Keys.",
      "password": true
    }
  ],
  "servers": {
    "srgplus": {
      "type": "stdio",
      "command": "uvx",
      "args": [
        "srgplus-mcp@0.4.7"
      ],
      "env": {
        "SRG_API_KEYS": "${input:srg-api-keys}"
      }
    }
  }
}
